import{z as i,x as n,o as B,c as l,q as A,j as t,D as a,d as s,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"测试与仿真","description":"","frontmatter":{"title":"测试与仿真","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-testing-simulation.md","filePath":"cs/emb-testing-simulation.md","lastUpdated":1791413859000}'),C={name:"cs/emb-testing-simulation.md"};function F(d,E,p,m,c,h){const e=n("Mermaid");return B(),l("div",null,[E[2]||(E[2]=A('<h1 id="测试与仿真" tabindex="-1">测试与仿真 <a class="header-anchor" href="#测试与仿真" aria-label="Permalink to &quot;测试与仿真&quot;">​</a></h1><div class="epigraph"><p>固件测试的难点从来不是「没有断言」，而是被测对象长在硬件上：没有板子跑不了，插着调试器跑又变了样，时间本身就是行为的一半。</p><footer>—— 据 MISRA C:2012；Renode 与 QEMU 的嵌入式测试实践整理</footer></div><p><a href="/cs/emb-security">上一课</a>要求在攻击者之前先找出自己的漏洞，而「找出」靠的是一套能日常运行的测试体系。固件测试比应用软件难在两处：代码绑在硬件上，板子没到位一切停摆；行为的一半是时间——只看「算得对不对」的测试，测不出「来不来得及」。缺口是<strong>把被测对象从硬件上分层剥下来</strong>：哪些逻辑在开发机测，哪些在仿真器里测，哪些只能上真实硬件，各归各位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把所有测试都推到「上板手动跑」，代价是三个。慢：一次全流程回归要人在场点按半天，没人愿意天天跑，回归只能靠用户报障。测不到：真实故障路径——看门狗复位后恢复是否正确、总线卡死能否解救——恰恰是手动流程里不敢按、也按不准的。测不准：printf 走 UART 会拖住时序，10 个字节在 115200 波特率下要近一毫秒，一个毫秒级控制循环被日志彻底改形。缺口的本质是<strong>可测性没有被设计进去</strong>：代码与硬件的边界若不在架构上切开，测试就只能从最贵的那一层开始。</p><p><span class="marginnote">「可测性是设计进去的」可以这么理解：像房子要预留检修口，固件要在架构上留一道缝——逻辑层只认接口，不直接摸寄存器。缝留好了，测试就能把「假硬件」塞进接口后面；没留缝，再多测试意愿也只能从拆墙开始。</span></p><h3 id="从逻辑里剥离硬件" tabindex="-1">从逻辑里剥离硬件 <a class="header-anchor" href="#从逻辑里剥离硬件" aria-label="Permalink to &quot;从逻辑里剥离硬件&quot;">​</a></h3><p>分层的第一刀是把「纯逻辑」从硬件访问里剥出来：协议解析、状态机、补偿算法，都不该直接摸寄存器。硬件访问收敛到一层薄抽象（HAL），逻辑层只依赖接口；到了开发机上，接口后面换成假实现——喂一段录制的传感器字节流，断言解析器的输出与状态迁移。同一份固件代码，在开发机上跑的是逻辑的真实、硬件的假象；这一刀切干净了，单元测试才有立锥之地。</p>',8)),(B(),t(o,null,{default:a(()=>[r(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOGIC%5B%22%E7%BA%AF%E9%80%BB%E8%BE%91%EF%BC%9A%E8%A7%A3%E6%9E%90%E3%80%81%E7%8A%B6%E6%80%81%E6%9C%BA%E3%80%81%E7%AE%97%E6%B3%95%22%5D%20--%3E%7C%22%E5%BC%80%E5%8F%91%E6%9C%BA%EF%BC%9A%E5%81%87%E7%A1%AC%E4%BB%B6%E5%AE%9E%E7%8E%B0%22%7C%20HOST%5B%22%E5%8D%95%E5%85%83%E6%B5%8B%E8%AF%95%EF%BC%8C%E7%A7%92%E7%BA%A7%E5%8F%8D%E9%A6%88%22%5D%0A%20%20SIM%5B%22%E4%BB%BF%E7%9C%9F%E5%99%A8%EF%BC%9AQEMU%2FRenode%20%E8%B7%91%E5%90%8C%E4%B8%80%E5%9B%BA%E4%BB%B6%22%5D%20--%3E%7C%22CI%20%E9%87%8C%E6%AF%8F%E6%AC%A1%E6%8F%90%E4%BA%A4%22%7C%20SIMT%5B%22%E5%90%AF%E5%8A%A8%E3%80%81%E5%8D%87%E7%BA%A7%E3%80%81%E6%81%A2%E5%A4%8D%E8%B7%AF%E5%BE%84%E5%9B%9E%E5%BD%92%22%5D%0A%20%20HIL%5B%22HIL%20%E5%8F%B0%E6%9E%B6%EF%BC%9A%E7%9C%9F%E5%AE%9E%E6%9D%BF%E5%8A%A0%E5%8F%97%E6%8E%A7%E6%BF%80%E5%8A%B1%22%5D%20--%3E%7C%22%E5%A4%9C%E9%97%B4%E6%88%96%E5%8F%91%E7%89%88%E5%89%8D%22%7C%20HILT%5B%22%E6%97%B6%E5%BA%8F%E3%80%81%E6%8A%96%E5%8A%A8%E3%80%81%E6%95%85%E9%9A%9C%E6%B3%A8%E5%85%A5%22%5D%0A%20%20FIELD%5B%22%E7%8E%B0%E5%9C%BA%E9%81%A5%E6%B5%8B%E4%B8%8E%20OTA%20%E5%9B%9E%E6%BB%9A%E6%97%A5%E5%BF%97%22%5D%20--%3E%7C%22%E4%B8%8A%E7%BA%BF%E5%90%8E%22%7C%20FB%5B%22%E5%8F%8D%E5%93%BA%E4%B8%8B%E4%B8%80%E8%BD%AE%E6%B5%8B%E8%AF%95%E7%94%A8%E4%BE%8B%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">故障注入是固件测试的独门科目：在随机位置注入一次延迟或损坏一帧数据，看看门狗、复位、恢复路径是否各就各位。上一课设计的那条失效梯子，只有在这里被反复踩过，才敢说它在现场会工作。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地按四层金字塔排布。底层单元测试在开发机跑，目标秒级反馈，覆盖解析与状态机的边界——I2C 的 NAK、半包、粘包都做成用例。第二层仿真回归：QEMU 或 Renode 启动同一份固件镜像，验证<a href="/cs/emb-bare-metal-boot">裸机启动</a>、<a href="/cs/emb-ota-updates">OTA 更新</a>的断电与回滚流程——这些「多次重启加写入」的路径在真实板上慢而脆弱，在仿真器里可以每次提交都跑。第三层 HIL 台架：真实板加可编程电源与信号源，专测仿真器给不了的时序——唤醒延迟、抖动分布、欠压行为，并在这里跑故障注入。第四层现场遥测：复位原因计数、栈高水位、看门狗触发率，回传后变成下一轮用例。静态分析贯穿四层：MISRA C 挡住大半未定义行为，比动态测试便宜。</p><p><span class="marginnote">HIL（硬件在环）就是「真板子加假世界」：板子是真的，但它的传感器输入、电源曲线都由可编程信号源扮演——想让它欠压就欠压，想喂坏帧就喂坏帧。专门测那些你在真实环境里不敢按、也按不准的按钮。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层之所以成立，依赖一个架构事实：<strong>固件的多数缺陷是逻辑缺陷</strong>，只有少数是时序与硬件交互缺陷——把两类分开测，便宜的工具覆盖多数，昂贵的工具聚焦少数。仿真器的机制价值在于<strong>重启的廉价</strong>：断电恢复、看门狗超时、升级中断这类「重启密集」的路径，真实板上一次几分钟，仿真器里一秒几十次，回归频率因此完全不同。但仿真保真度要诚实对待：外设模型常常是功能级的，I2C 上升时间、电源跌落的边沿都不在里面——所以 HIL 层不可省，时序类结论只认真实硬件。<a href="/cs/emb-rtos">RTOS</a> 的调度抖动同理：仿真器里的延迟数字不构成证据。</p>',6)),(B(),t(o,null,{default:a(()=>[r(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%96%B0%E5%A2%9E%E4%B8%80%E4%B8%AA%E6%B5%8B%E8%AF%95%E7%94%A8%E4%BE%8B%22%5D%20--%3E%20Q1%7B%22%E5%8F%AA%E6%B6%89%E5%8F%8A%E7%BA%AF%E9%80%BB%E8%BE%91%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20L1%5B%22%E5%BC%80%E5%8F%91%E6%9C%BA%E5%8D%95%E5%85%83%E6%B5%8B%E8%AF%95%EF%BC%9A%E7%A7%92%E7%BA%A7%E5%8F%8D%E9%A6%88%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E8%B7%AF%E5%BE%84%E8%A6%81%E5%8F%8D%E5%A4%8D%E9%87%8D%E5%90%AF%E6%88%96%E6%96%AD%E7%94%B5%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20L2%5B%22%E4%BB%BF%E7%9C%9F%E5%99%A8%E5%9B%9E%E5%BD%92%EF%BC%9A%E9%87%8D%E5%90%AF%E5%BB%89%E4%BB%B7%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20Q3%7B%22%E7%BB%93%E8%AE%BA%E4%BE%9D%E8%B5%96%E7%9C%9F%E5%AE%9E%E6%97%B6%E5%BA%8F%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20L3%5B%22HIL%20%E5%8F%B0%E6%9E%B6%EF%BC%9A%E5%8F%AA%E8%AE%A4%E7%9C%9F%E5%AE%9E%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20L2%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">初学者容易以为「仿真器全绿」就能发版；仿真器的外设模型是功能级的，I2C 的上升时间、电源跌落的边沿都不在模型里。仿真的绿只担保逻辑正确，时序类的结论必须回到真实硬件上重新下——两层的判词不通用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写的是固件与板级测试，不写两块。芯片内部的制造测试——扫描链、内建自测——是<a href="/cs/dft-scan-chain">可测性设计与扫描链</a>与<a href="/cs/bist">内建自测</a>的世界，固件工程师是用户而非作者；RTL 级验证与测试平台在<a href="/cs/verification-testbench">验证与测试平台</a>讲过。形式化验证只点名：关键状态机可用模型检查穷举，成本高，只配给出错即事故的模块。最后一条纪律：HIL 台架要当产品的一部分维护——用例版本化、台架自检、坏了先修；带病的台架会污染所有发版决策，比没有台架更糟。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可测性是架构属性：HAL 把硬件访问切薄，纯逻辑才能在开发机秒级回归。</li><li>四层金字塔：单元测试、仿真回归、HIL 时序与故障注入、现场遥测反哺用例。</li><li>仿真器的价值在重启廉价，适合升级与恢复路径；时序结论只认真实硬件。</li><li>故障注入把看门狗与恢复梯子踩实；MISRA 静态检查比动态测试便宜一个量级。</li><li>出处：MISRA C:2012；QEMU/Renode 文档与嵌入式 CI 实践；据本栏 emb-rtos、emb-watchdog-failsafe 两课的时序与失效口径整理。</li></ul>',5))])}const f=i(C,[["render",F]]);export{_ as __pageData,f as default};
